// Builds the Bill Tracker desk page script from the sources in this folder:
//   node ui/build.js  ->  bill_tracker/bill_tracker/page/bill_tracker/bill_tracker.js
// The page is a single DUX Digitech design-system app inside a Shadow DOM (list, detail, new/edit form,
// live payment calculation). Edit 01_util.js ... 04_boot.js / bt_ui.css, then rebuild; do not edit the generated file.
const fs = require("fs");
const path = require("path");

const here = __dirname;
const read = (f) => fs.readFileSync(path.join(here, f), "utf8");
const uri = (f) => "data:image/png;base64," + fs.readFileSync(path.join(here, "assets", f)).toString("base64");
const target = path.join(here, "..", "bill_tracker", "bill_tracker", "page", "bill_tracker", "bill_tracker.js");

const css = read("bt_ui.css");
if (css.includes("`") || css.includes("${")) throw new Error("bt_ui.css must not contain backticks or ${");
const img = JSON.stringify({ mark: uri("mark.png"), markW: uri("mark-white.png") });

let core = ["01_util.js", "02_app.js", "03_form.js", "03b_dashboard.js", "04_boot.js"].map(read).join("\n");
core = core.replace("/*__CSS__*/''", () => "`" + css + "`").replace("/*__IMG__*/{}", () => img);
if (core.includes("/*__")) throw new Error("placeholder left in core");

const BUILD = new Date().toISOString().replace(/[-:T]/g, "").slice(0, 14);
const page = `// Generated by ui/build.js (build ${BUILD}) - edit the sources in the ui/ folder, not this file.
frappe.provide("bill_tracker");

${core}

frappe.pages["bill-tracker"].on_page_load = function (wrapper) {
	const page = frappe.ui.make_app_page({
		parent: wrapper,
		title: __("Bill Tracker"),
		single_column: true,
	});
	// the DUX header inside the page replaces the standard Desk title bar
	$(wrapper).find(".page-head").hide();
	wrapper.bill_tracker = window.BillTrackerUI.mount(page.main[0], { mode: "desk" });
};

frappe.pages["bill-tracker"].on_page_show = function (wrapper) {
	// pick up bills created / edited on the form while the page was in the background
	if (wrapper.bill_tracker) wrapper.bill_tracker.on_show();
};
`;
fs.writeFileSync(target, page);
console.log("built", target, page.length, "bytes");
